import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Local Server","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/local-server/local-server.md","filePath":"documentation/local-server/local-server.md","lastUpdated":1788551488000}`),a={name:`documentation/local-server/local-server.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="local-server" tabindex="-1">Local Server <a class="header-anchor" href="#local-server" aria-label="Permalink to “Local Server”">​</a></h1><p>The <strong>Local Server</strong> feature allows the Excellent Data Filler extension to communicate with a companion server application hosted locally on your machine. This unlocks advanced automation capabilities that require system-level or network-level operations, such as automated email dispatching, IMAP inbox verification, and secure local file processing.</p><p>To configure the server connection inside the extension, see the <a href="/documentation/settings.html#extension-server">Extension Server Settings</a> reference.</p><img src="/image/local-server-dashboard.png" alt="Local Server Dashboard" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h2><p>Follow these steps to set up and launch the Local Server:</p><h3 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to “Download”">​</a></h3><table tabindex="0"><thead><tr><th>Platform</th><th>Package</th><th>Version</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td><a href="/edf-server-v1.0.0.zip">Download EDF Server (.zip)</a></td><td>v1.0.0</td></tr></tbody></table><h3 id="how-to-run" tabindex="-1">How to Run <a class="header-anchor" href="#how-to-run" aria-label="Permalink to “How to Run”">​</a></h3><ol><li><strong>Download</strong>: Click the download link above to obtain <code>edf-server-v1.0.0.zip</code>.</li><li><strong>Extract</strong>: Right-click the downloaded zip archive and select <strong>Extract All...</strong> to unpack the files.</li><li><strong>Run Executable</strong>: Open the extracted folder and double-click <code>edf-server.exe</code>.</li><li><strong>Command Window</strong>: A console window will open, indicating that the server process is active.</li><li><strong>Browser Interface</strong>: The server web dashboard will launch automatically at <a href="http://127.0.0.10:8080/" target="_blank" rel="noreferrer">http://127.0.0.10:8080/</a>.</li></ol><h3 id="api-authorization-configuration" tabindex="-1">API Authorization Configuration <a class="header-anchor" href="#api-authorization-configuration" aria-label="Permalink to “API Authorization Configuration”">​</a></h3><p>To establish an authenticated bridge between the browser extension and your local server:</p><ol><li><strong>Open API Settings</strong>: Navigate to the server&#39;s API settings page: <a href="http://127.0.0.10:8080/settings/api" target="_blank" rel="noreferrer">http://127.0.0.10:8080/settings/api</a>.</li><li><strong>Enable Public API</strong>: Toggle the <strong>Public API</strong> switch to <strong>ON</strong>.</li><li><strong>Copy Token</strong>: In the <strong>API Authorization</strong> section, locate the <code>X-API-Token</code> value and click the copy icon.</li><li><strong>Configure Extension</strong>: Open the extension&#39;s <a href="/documentation/settings.html#extension-server">Settings</a>, locate the <strong>Extension Server</strong> section, and paste the token into the <strong>X-API-Token</strong> field.</li></ol><div class="tip custom-block"><p class="custom-block-title">Keep Server Running</p><p>Keep the command prompt window open while using local server automation features. Closing the console terminates the server process.</p></div><hr><h2 id="server-interface" tabindex="-1">Server Interface <a class="header-anchor" href="#server-interface" aria-label="Permalink to “Server Interface”">​</a></h2><p>The Local Server web portal provides several management utilities:</p><ul><li><strong>Dashboard</strong>: Monitor real-time server status, uptime, and active extension connections.</li><li><strong><a href="/documentation/local-server/mail-accounts.html">Mail Accounts</a></strong>: Register and configure IMAP/SMTP email accounts for automation workflows.</li><li><strong>API Settings</strong>: Manage API authorization keys and toggle extension access.</li><li><strong>Audit Logs</strong>: Inspect a detailed chronological log of all incoming requests and operations.</li></ul><hr><h2 id="where-to-use" tabindex="-1">Where to Use <a class="header-anchor" href="#where-to-use" aria-label="Permalink to “Where to Use”">​</a></h2><p>The Local Server is utilized by automation fields that require background network or OS access:</p><ul><li><strong><a href="/documentation/field-types/local-server/get-mail-from-local-server.html">Get Mail from Local Server</a></strong>: Automatically retrieve emails or verification codes via IMAP.</li><li><strong><a href="/documentation/field-types/local-server/send-mail-from-local-server.html">Send Mail from Local Server</a></strong>: Dispatch emails automatically via SMTP.</li></ul><p>For a summary of all server-assisted fields, visit the <a href="/documentation/form-fields/field-types.html#local-server">Local Server Field Types</a> catalog.</p><hr><h2 id="security-considerations" tabindex="-1">Security Considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to “Security Considerations”">​</a></h2><ul><li><strong>Local Execution</strong>: All communications between the extension and the server occur strictly over <code>localhost</code> (<code>127.0.0.10</code>).</li><li><strong>No Cloud Transmission</strong>: Account credentials and automated payloads are never sent to external servers or third-party clouds.</li><li><strong>Token Protection</strong>: Extension requests are authenticated using your unique local <code>X-API-Token</code>.</li></ul>`,27)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};